{ const nIL=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Jerusalem'})); const curTab=['ינואר','פברואר','מרץ','אפריל','מאי','יוני','יולי','אוגוסט','ספטמבר','אוקטובר','נובמבר','דצמבר'][nIL.getMonth()]+' '+nIL.getFullYear();
